import unittest
from candidate import derivative

class TestDerivative(unittest.TestCase):
    def test_derivative_constant(self):
        self.assertEqual(derivative([3]), [])

    def test_derivative_linear(self):
        self.assertEqual(derivative([3, 1]), [1])

    def test_derivative_quadratic(self):
        self.assertEqual(derivative([3, 1, 2]), [1, 4])

    def test_derivative_cubic(self):
        self.assertEqual(derivative([3, 1, 2, 4]), [1, 4, 12])

    def test_derivative_high_degree(self):
        self.assertEqual(derivative([3, 1, 2, 4, 5]), [1, 4, 12, 20])

    def test_derivative_empty_input(self):
        self.assertEqual(derivative([]), [])

    def test_derivative_single_element_input(self):
        self.assertEqual(derivative([3]), [])

    def test_derivative_none_input(self):
        with self.assertRaises(TypeError):
            derivative(None)

    def test_derivative_non_list_input(self):
        with self.assertRaises(TypeError):
            derivative('123')

    def test_derivative_non_numeric_coefficients(self):
        with self.assertRaises(TypeError):
            derivative([3, 1, 'a', 4])

if __name__ == '__main__':
    unittest.main()
